// static
bool StructTraits<::organizer_panel::mojom::ForeignTab::DataView, ::organizer_panel::mojom::ForeignTabPtr>::Read(
    ::organizer_panel::mojom::ForeignTab::DataView input,
    ::organizer_panel::mojom::ForeignTabPtr* output) {
  bool success = true;
  ::organizer_panel::mojom::ForeignTabPtr result(::organizer_panel::mojom::ForeignTab::New());
  
      if (success && !input.ReadSessionTag(&result->session_tag))
        success = false;
      if (success)
        result->session_tab_id = input.session_tab_id();
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadUrl(&result->url))
        success = false;
      if (success && !input.ReadLastActiveElapsedText(&result->last_active_elapsed_text))
        success = false;
      if (success && !input.ReadDeviceName(&result->device_name))
        success = false;
  *output = std::move(result);
  return success;
}

