void ForeignTabsPageHandlerAsyncWaiter::GetForeignTabs(
    std::vector<ForeignTabPtr>* out_tabs) {
  base::RunLoop loop;
  proxy_->GetForeignTabs(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<ForeignTabPtr>* out_tabs
,
             std::vector<ForeignTabPtr> tabs) {*out_tabs = std::move(tabs);
            loop->Quit();
          },
          &loop,
          out_tabs));
  loop.Run();
}

